:root {
  --gold: #e8b866;
  --gold-bright: #ffd98a;
  --gold-deep: #a9762f;
  --ink: #06120d;
  --ink-2: #0a1b14;
  --cream: #f3e8cf;
  --muted: #c9c3ae;
  --line: rgba(232, 184, 102, .3);
  --panel: rgba(8, 22, 17, .84);
  --serif: Georgia, "Times New Roman", "Nimbus Roman", serif;
  --sans: "Trebuchet MS", "Segoe UI", Tahoma, Verdana, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  overflow: hidden;
  background: #04100b;
  color: var(--cream);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}

body {
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
  touch-action: none;
}

button { font-family: inherit; }

#app {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  height: 100dvh;
  overflow: hidden;
  isolation: isolate;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  background: #071a12;
}

/* ---------- shared bits ---------- */

.is-hidden {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
}

.kicker {
  display: flex;
  align-items: center;
  gap: 14px;
  color: var(--gold);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .42em;
  text-transform: uppercase;
  text-shadow: 0 1px 8px rgba(0, 0, 0, .6);
}
.kicker span {
  width: 34px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--gold));
  opacity: .75;
}
.kicker span:last-child {
  transform: scaleX(-1);
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--gold);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .3em;
  text-transform: uppercase;
}
.eyebrow .dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--gold-bright);
  box-shadow: 0 0 8px rgba(255, 217, 138, .9);
}

/* ---------- title ---------- */

.title-screen {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  padding: clamp(22px, 6vw, 96px);
  background:
    linear-gradient(90deg, rgba(2, 10, 7, .93) 0%, rgba(3, 14, 10, .77) 32%, rgba(3, 14, 10, .3) 62%, rgba(2, 10, 7, .58) 100%),
    linear-gradient(0deg, rgba(2, 9, 6, .8) 0%, rgba(2, 9, 6, 0) 38%);
  transition: opacity 1s ease, visibility 1s;
}
.title-screen.is-hidden { opacity: 0; visibility: hidden; }

.title-glow {
  position: absolute;
  width: 62vmax;
  height: 62vmax;
  left: -16vmax;
  top: 44%;
  transform: translateY(-50%);
  background: radial-gradient(circle, rgba(224, 171, 80, .18), rgba(224, 171, 80, .04) 46%, transparent 70%);
  pointer-events: none;
}

.title-inner {
  position: relative;
  z-index: 2;
  width: min(620px, 100%);
  animation: title-in 1.2s cubic-bezier(.2, .8, .2, 1) both;
}
@keyframes title-in {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: translateY(0); }
}

.game-title {
  margin: 18px 0 0;
  font-family: var(--serif);
  font-size: clamp(76px, 10.5vw, 148px);
  font-weight: 400;
  line-height: .82;
  letter-spacing: .015em;
  background: linear-gradient(178deg, #fff8e4 4%, #f4d492 32%, #d8a04b 62%, #93601f 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 12px 30px rgba(0, 0, 0, .62)) drop-shadow(0 0 42px rgba(232, 184, 102, .14));
}

.ornament {
  display: flex;
  align-items: center;
  gap: 14px;
  width: min(100%, 430px);
  margin: 20px 0 12px;
  color: var(--gold);
}
.ornament i {
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(232, 184, 102, .8));
}
.ornament i:last-child { transform: scaleX(-1); }
.ornament svg { width: 15px; height: 15px; opacity: .9; filter: drop-shadow(0 0 6px rgba(232,184,102,.5)); }

.subtitle {
  margin: 0;
  color: #eadcbc;
  font-size: clamp(13px, 1.6vw, 17px);
  font-weight: 400;
  letter-spacing: .52em;
  text-transform: uppercase;
  text-shadow: 0 2px 14px rgba(0, 0, 0, .8);
}

.lede {
  max-width: 46ch;
  margin: 26px 0 30px;
  color: #d7d0bd;
  font-family: var(--serif);
  font-size: clamp(15px, 1.5vw, 18px);
  line-height: 1.72;
  text-shadow: 0 2px 18px rgba(0, 0, 0, .7);
}

.start-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 16px;
  padding: 16px 26px 16px 30px;
  border: 1px solid rgba(255, 228, 170, .75);
  border-radius: 2px;
  background: linear-gradient(135deg, #f3d99b 0%, #e4b768 42%, #c38a36 100%);
  color: #1b1308;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .26em;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow: 0 14px 40px rgba(0, 0, 0, .45), 0 0 0 0 rgba(255, 217, 138, .32), inset 0 1px 0 rgba(255, 255, 255, .55);
  transition: transform .25s ease, box-shadow .25s ease, filter .25s ease;
  animation: cta-breathe 4.2s ease-in-out infinite;
}
.start-btn::before {
  content: "";
  position: absolute;
  inset: 3px;
  border: 1px solid rgba(70, 45, 12, .3);
  pointer-events: none;
}
.start-btn svg { width: 18px; height: 18px; transition: transform .25s ease; }
.start-btn:hover { transform: translateY(-2px); filter: brightness(1.06); box-shadow: 0 18px 50px rgba(0, 0, 0, .5), 0 0 34px rgba(232, 184, 102, .28), inset 0 1px 0 rgba(255, 255, 255, .6); }
.start-btn:hover svg { transform: translateX(3px); }
.start-btn:active { transform: translateY(0) scale(.99); }
@keyframes cta-breathe {
  0%, 100% { box-shadow: 0 14px 40px rgba(0, 0, 0, .45), 0 0 0 0 rgba(255, 217, 138, .28), inset 0 1px 0 rgba(255, 255, 255, .55); }
  50% { box-shadow: 0 14px 44px rgba(0, 0, 0, .48), 0 0 30px rgba(255, 217, 138, .22), inset 0 1px 0 rgba(255, 255, 255, .6); }
}

.title-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
  margin-top: 30px;
  color: #bcb7a5;
  font-size: 10px;
  letter-spacing: .16em;
  text-transform: uppercase;
}
.title-meta b { color: var(--gold-bright); font-size: 12px; }
.meta-sep { width: 3px; height: 3px; border-radius: 50%; background: rgba(232, 184, 102, .5); }
.meta-item { display: inline-flex; align-items: center; gap: 5px; }

.controls-line {
  margin-top: 24px;
  color: rgba(218, 211, 193, .55);
  font-size: 10px;
  letter-spacing: .12em;
}
.touch-only { display: none; }
body.touch .desktop-only { display: none; }
body.touch .touch-only { display: inline; }

.title-footer {
  position: absolute;
  left: clamp(22px, 6vw, 96px);
  right: clamp(22px, 6vw, 96px);
  bottom: max(20px, env(safe-area-inset-bottom));
  display: flex;
  align-items: center;
  gap: 12px;
  color: rgba(214, 208, 190, .32);
  font-size: 9px;
  letter-spacing: .18em;
  text-transform: uppercase;
}
.footer-gem { color: rgba(232, 184, 102, .4); }

/* ---------- HUD ---------- */

#hud {
  position: absolute;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  transition: opacity .6s ease, visibility .6s;
}

.hud-top {
  position: absolute;
  top: max(14px, env(safe-area-inset-top));
  left: max(14px, env(safe-area-inset-left));
  right: max(14px, env(safe-area-inset-right));
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.objective-card {
  width: min(330px, 42vw);
  padding: 13px 16px 12px;
  border: 1px solid rgba(232, 184, 102, .24);
  border-left: 2px solid rgba(232, 184, 102, .8);
  border-radius: 9px;
  background: linear-gradient(155deg, rgba(10, 28, 21, .92), rgba(5, 16, 12, .72));
  box-shadow: 0 16px 40px rgba(0, 0, 0, .32), inset 0 1px 0 rgba(255, 255, 255, .04);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.objective-text {
  margin: 7px 0 11px;
  color: #f3ead8;
  font-size: 14px;
  line-height: 1.35;
  letter-spacing: .01em;
  text-shadow: 0 1px 8px rgba(0, 0, 0, .5);
}

.glyphs {
  display: flex;
  align-items: center;
  gap: 8px;
}
.glyph {
  position: relative;
  display: grid;
  place-items: center;
  width: 33px;
  height: 33px;
  border: 1px solid rgba(232, 184, 102, .22);
  border-radius: 50%;
  background: radial-gradient(circle at 50% 35%, rgba(232, 184, 102, .07), rgba(0, 0, 0, .28));
  color: #748173;
  opacity: .68;
  transition: all .7s cubic-bezier(.2, .8, .2, 1);
}
.glyph svg { width: 17px; height: 17px; }
.glyph.found {
  color: var(--gold-bright);
  opacity: 1;
  border-color: rgba(255, 217, 138, .7);
  background: radial-gradient(circle at 50% 32%, rgba(255, 217, 138, .3), rgba(57, 40, 12, .45));
  box-shadow: 0 0 18px rgba(232, 184, 102, .38), inset 0 0 10px rgba(255, 217, 138, .18);
  transform: translateY(-1px);
}
.glyph.found::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 1px solid rgba(255, 217, 138, .18);
  animation: glyph-pulse 2.4s ease-in-out infinite;
}
@keyframes glyph-pulse {
  0%, 100% { transform: scale(1); opacity: .7; }
  50% { transform: scale(1.06); opacity: .2; }
}
.glyph-count {
  margin-left: 3px;
  color: rgba(232, 184, 102, .75);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .12em;
}

.compass-wrap {
  position: absolute;
  left: 50%;
  top: 0;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  filter: drop-shadow(0 8px 18px rgba(0, 0, 0, .5));
}
.compass {
  position: relative;
  width: 82px;
  height: 82px;
  border-radius: 50%;
  border: 1px solid rgba(232, 184, 102, .42);
  background:
    radial-gradient(circle at 50% 38%, rgba(20, 45, 34, .94), rgba(5, 16, 12, .92)),
    var(--panel);
  box-shadow: inset 0 0 22px rgba(0, 0, 0, .6), 0 0 0 4px rgba(6, 18, 13, .35);
}
.compass::before {
  content: "";
  position: absolute;
  inset: 5px;
  border-radius: 50%;
  border: 1px solid rgba(232, 184, 102, .16);
}
.compass-ticks {
  position: absolute;
  inset: 8px;
  border-radius: 50%;
  background: repeating-conic-gradient(from 0deg, rgba(232, 184, 102, .52) 0deg .8deg, transparent .8deg 30deg);
  -webkit-mask: radial-gradient(circle, transparent 63%, #000 64%);
  mask: radial-gradient(circle, transparent 63%, #000 64%);
  opacity: .8;
}
.compass-n {
  position: absolute;
  top: 5px;
  left: 50%;
  transform: translateX(-50%);
  color: var(--gold);
  font-family: var(--serif);
  font-size: 9px;
  letter-spacing: .1em;
}
.needle-wrap {
  position: absolute;
  inset: 0;
  transform: rotate(0deg);
}
.needle {
  position: absolute;
  left: calc(50% - 1px);
  top: 14px;
  width: 2px;
  height: 27px;
  border-radius: 2px;
  background: linear-gradient(180deg, transparent 0%, var(--gold-bright) 30%, var(--gold-bright) 100%);
  transform-origin: 50% 27px;
  box-shadow: 0 0 7px rgba(255, 217, 138, .8);
}
.needle::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -2px;
  width: 6px;
  height: 6px;
  transform: translateX(-50%) rotate(45deg);
  background: var(--gold-bright);
  box-shadow: 0 0 8px rgba(255, 217, 138, .9);
}
.compass-core {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 7px;
  height: 7px;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 10px rgba(255, 217, 138, .7);
}
.compass-caption {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 4px 10px;
  border: 1px solid rgba(232, 184, 102, .18);
  border-radius: 99px;
  background: rgba(5, 17, 12, .72);
  color: #e6dcc4;
  font-size: 9px;
  letter-spacing: .14em;
  text-transform: uppercase;
  white-space: nowrap;
  backdrop-filter: blur(8px);
}
.compass-caption span:last-child { color: rgba(232, 184, 102, .8); }

.top-actions {
  display: flex;
  gap: 8px;
  pointer-events: auto;
}
.round-btn {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border: 1px solid rgba(232, 184, 102, .26);
  border-radius: 50%;
  background: rgba(6, 20, 14, .72);
  color: var(--gold);
  cursor: pointer;
  backdrop-filter: blur(10px);
  transition: background .2s, border-color .2s, transform .2s;
}
.round-btn:hover { background: rgba(16, 39, 28, .9); border-color: rgba(232, 184, 102, .55); transform: translateY(-1px); }
.round-btn svg { width: 18px; height: 18px; }
.round-btn .mute-line { opacity: 0; transition: opacity .2s; }
.round-btn .waves { opacity: 1; transition: opacity .2s; }
.round-btn.muted .mute-line { opacity: 1; }
.round-btn.muted .waves { opacity: 0; }

/* ---------- prompt / toast ---------- */

.prompt {
  position: absolute;
  left: 50%;
  bottom: max(34px, calc(env(safe-area-inset-bottom) + 18px));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 9px 16px 9px 10px;
  border: 1px solid rgba(232, 184, 102, .34);
  border-radius: 99px;
  background: linear-gradient(180deg, rgba(11, 30, 22, .94), rgba(5, 17, 12, .88));
  box-shadow: 0 12px 30px rgba(0, 0, 0, .42), inset 0 1px 0 rgba(255, 255, 255, .05);
  color: #f2e8d3;
  font-size: 12px;
  letter-spacing: .04em;
  white-space: nowrap;
  backdrop-filter: blur(10px);
  transition: opacity .2s, transform .25s, visibility .2s;
  z-index: 12;
}
.prompt.is-hidden { opacity: 0; visibility: hidden; transform: translate(-50%, 8px); }
.prompt kbd, .key-hint kbd {
  display: inline-grid;
  place-items: center;
  min-width: 24px;
  height: 24px;
  padding: 0 6px;
  border: 1px solid rgba(232, 184, 102, .5);
  border-radius: 5px;
  background: rgba(232, 184, 102, .09);
  color: var(--gold-bright);
  font-family: var(--sans);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .06em;
  box-shadow: 0 2px 0 rgba(0, 0, 0, .35);
}

.toast {
  position: absolute;
  left: 50%;
  top: max(110px, calc(env(safe-area-inset-top) + 100px));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  max-width: min(500px, calc(100vw - 32px));
  padding: 10px 18px;
  border: 1px solid rgba(232, 184, 102, .22);
  border-radius: 99px;
  background: rgba(6, 20, 14, .86);
  box-shadow: 0 14px 36px rgba(0, 0, 0, .4);
  color: #eee4cd;
  font-size: 11px;
  letter-spacing: .05em;
  text-align: center;
  backdrop-filter: blur(10px);
  transition: opacity .4s, transform .4s, visibility .4s;
  z-index: 13;
}
.toast.is-hidden { opacity: 0; visibility: hidden; transform: translate(-50%, -8px); }
.toast-gem {
  flex: 0 0 auto;
  width: 7px;
  height: 7px;
  transform: rotate(45deg);
  background: var(--gold-bright);
  box-shadow: 0 0 9px rgba(255, 217, 138, .8);
}

/* ---------- dialogue ---------- */

.dialogue {
  position: absolute;
  left: 50%;
  bottom: max(26px, calc(env(safe-area-inset-bottom) + 16px));
  transform: translate(-50%, 14px);
  width: min(780px, calc(100vw - 40px));
  display: grid;
  grid-template-columns: 62px 1fr;
  gap: 17px;
  padding: 18px 22px 20px;
  border: 1px solid rgba(232, 184, 102, .32);
  border-radius: 14px;
  background: linear-gradient(160deg, rgba(11, 31, 23, .97), rgba(4, 15, 11, .94));
  box-shadow: 0 30px 80px rgba(0, 0, 0, .6), inset 0 1px 0 rgba(255, 255, 255, .06);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  z-index: 20;
  opacity: 1;
  visibility: visible;
  transition: opacity .3s, transform .35s, visibility .3s;
}
.dialogue.is-hidden { opacity: 0; visibility: hidden; transform: translate(-50%, 20px); }
.dialogue::before {
  content: "";
  position: absolute;
  left: 22px;
  right: 22px;
  top: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(232, 184, 102, .55), transparent);
}
.portrait {
  position: relative;
  display: grid;
  place-items: center;
  width: 62px;
  height: 62px;
  border-radius: 50%;
  border: 1px solid rgba(232, 184, 102, .5);
  background:
    radial-gradient(circle at 50% 30%, rgba(232, 184, 102, .3), rgba(12, 32, 23, .9) 66%),
    #0a1e16;
  box-shadow: inset 0 0 18px rgba(0, 0, 0, .6), 0 0 20px rgba(232, 184, 102, .12);
  color: var(--gold-bright);
  font-family: var(--serif);
  font-size: 26px;
}
.portrait::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 1px solid rgba(232, 184, 102, .16);
}
.dialogue-body { min-width: 0; }
.speaker {
  margin-bottom: 5px;
  color: var(--gold);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .28em;
  text-transform: uppercase;
}
.dialogue-body p {
  margin: 0;
  min-height: 44px;
