.dialogue-next span { font-size: 12px; animation: nudge 1.4s ease-in-out infinite; }
@keyframes nudge { 0%, 100% { transform: translateX(0); } 50% { transform: translateX(3px); } }

/* ---------- key hint ---------- */

.key-hint {
  position: absolute;
  left: max(18px, env(safe-area-inset-left));
