  flex-wrap: wrap;
  gap: 13px;
  color: rgba(226, 219, 201, .52);
  font-size: 9px;
  letter-spacing: .12em;
  text-transform: uppercase;
  transition: opacity 1s;
  pointer-events: none;
}
.key-hint span { display: inline-flex; align-items: center; gap: 6px; }
.key-hint kbd { min-width: 20px; height: 20px; padding: 0 5px; font-size: 8px; }
.key-hint.fade { opacity: 0; }

/* ---------- touch ---------- */

.touch-controls { display: none; }
body.touch .touch-controls {
  display: flex;
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 14;
}
.joystick {
  position: absolute;
