}
@keyframes action-pulse {
  0%, 100% { box-shadow: 0 0 18px rgba(232, 184, 102, .22), inset 0 0 12px rgba(232, 184, 102, .1); }
  50% { box-shadow: 0 0 40px rgba(255, 217, 138, .46), inset 0 0 22px rgba(232, 184, 102, .24); }
}

body.touch .key-hint { display: none; }
body.touch .prompt { bottom: max(176px, calc(env(safe-area-inset-bottom) + 166px)); }
body.touch .dialogue { bottom: max(18px, calc(env(safe-area-inset-bottom) + 10px)); }
body.touch .dialogue-open .touch-controls { opacity: 0; visibility: hidden; }
.dialogue-open .touch-controls { opacity: 0; visibility: hidden; transition: opacity .2s, visibility .2s; }

/* ---------- ending ---------- */

.ending {
  position: absolute;
  inset: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: center;
