  .compass { width: 62px; height: 62px; }
  .needle { top: 10px; height: 21px; transform-origin: 50% 21px; }
  .compass-caption { font-size: 8px; gap: 5px; padding: 3px 8px; }
  .compass-n { top: 3px; font-size: 7px; }
  .round-btn { width: 36px; height: 36px; }
  .round-btn svg { width: 16px; height: 16px; }
  .toast { top: max(118px, calc(env(safe-area-inset-top) + 108px)); font-size: 10px; padding: 8px 14px; }
  .dialogue { grid-template-columns: 48px 1fr; gap: 12px; padding: 14px 16px 16px; }
  .portrait { width: 48px; height: 48px; font-size: 21px; }
  .dialogue-body p { font-size: 14px; line-height: 1.55; min-height: 58px; }
  .dialogue-next { right: 10px; bottom: 8px; font-size: 8px; }
