// ---------- math ----------

export function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }
export function lerp(a, b, t) { return a + (b - a) * t; }
export function invLerp(a, b, v) { return clamp((v - a) / (b - a), 0, 1); }
export function smoothstep(t) { t = clamp(t, 0, 1); return t * t * (3 - 2 * t); }
export function easeInOut(t) { t = clamp(t, 0, 1); return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; }
export function easeOut(t) { t = clamp(t, 0, 1); return 1 - Math.pow(1 - t, 3); }
export function dist2(ax, ay, bx, by) { const dx = ax - bx, dy = ay - by; return dx * dx + dy * dy; }
export function dist(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
export function angleTo(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax); }

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function random() {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function formatTime(seconds) {
  const s = Math.max(0, Math.floor(seconds));
  return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
}

// ---------- path helpers ----------

export function buildPathSamples(paths, step = 22) {
  const out = [];
  for (const pts of paths) {
    for (let i = 0; i < pts.length - 1; i += 1) {
      const [x1, y1] = pts[i];
      const [x2, y2] = pts[i + 1];
      const len = Math.hypot(x2 - x1, y2 - y1);
      const count = Math.max(1, Math.ceil(len / step));
      for (let j = 0; j <= count; j += 1) {
        const t = j / count;
        out.push([x1 + (x2 - x1) * t, y1 + (y2 - y1) * t]);
      }
    }
  }
  return out;
}

export const PATH_SAMPLES = buildPathSamples(PATHS);

export function distanceToPath(x, y) {
  let best = Infinity;
  for (const [px, py] of PATH_SAMPLES) {
    const d = (px - x) * (px - x) + (py - y) * (py - y);
    if (d < best) best = d;
  }
  return Math.sqrt(best);
}

export function insideClearing(x, y, pad = 1) {
  return CLEARINGS.some(c => {
    const nx = (x - c.x) / (c.rx * pad);
    const ny = (y - c.y) / (c.ry * pad);
    return nx * nx + ny * ny < 1;
  });
}

export function inReserved(x, y, pad = 0) {
  return RESERVED.some(([rx, ry, rw, rh]) =>
    x > rx - pad && x < rx + rw + pad && y > ry - pad && y < ry + rh + pad);
}

export function inRiver(x, y, pad = 0) {
  return x > RIVER.x1 - pad && x < RIVER.x2 + pad && y > -pad && y < H + pad;
}

// ---------- drawing helpers ----------

export function rrect(g, x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h / 2);
  g.beginPath();
  g.moveTo(x + rr, y);
  g.lineTo(x + w - rr, y);
  g.quadraticCurveTo(x + w, y, x + w, y + rr);
  g.lineTo(x + w, y + h - rr);
  g.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
  g.lineTo(x + rr, y + h);
  g.quadraticCurveTo(x, y + h, x, y + h - rr);
  g.lineTo(x, y + rr);
  g.quadraticCurveTo(x, y, x + rr, y);
  g.closePath();
}

export function ellipse(g, x, y, rx, ry, fill) {
  g.beginPath();
  g.ellipse(x, y, rx, ry, 0, 0, TAU);
  if (fill) { g.fillStyle = fill; g.fill(); }
}

export function blob(g, cx, cy, rx, ry, points, rand, rot = 0) {
  const verts = [];
  for (let i = 0; i < points; i += 1) {
    const a = rot + (i / points) * TAU;
    const wobble = 0.78 + rand() * 0.36;
    verts.push([cx + Math.cos(a) * rx * wobble, cy + Math.sin(a) * ry * wobble]);
  }
  g.beginPath();
  for (let i = 0; i < verts.length; i += 1) {
    const p = verts[i];
    const next = verts[(i + 1) % verts.length];
    const mx = (p[0] + next[0]) / 2;
    const my = (p[1] + next[1]) / 2;
    if (i === 0) g.moveTo(mx, my);
    else g.quadraticCurveTo(p[0], p[1], mx, my);
    if (i === verts.length - 1) g.quadraticCurveTo(p[0], p[1], mx, my);
  }
  g.closePath();
}

export function smoothStroke(g, pts, width, color, alpha = 1) {
  if (pts.length < 2) return;
  g.save();
  g.globalAlpha = alpha;
  g.strokeStyle = color;
  g.lineWidth = width;
  g.lineCap = 'round';
  g.lineJoin = 'round';
  g.beginPath();
  g.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length - 1; i += 1) {
    const mx = (pts[i][0] + pts[i + 1][0]) / 2;
    const my = (pts[i][1] + pts[i + 1][1]) / 2;
    g.quadraticCurveTo(pts[i][0], pts[i][1], mx, my);
  }
  const last = pts[pts.length - 1];
  g.lineTo(last[0], last[1]);
  g.stroke();
  g.restore();
}

export function drawStar(g, x, y, outer, inner, points, color) {
  g.beginPath();
  for (let i = 0; i < points * 2; i += 1) {
    const r = i % 2 === 0 ? outer : inner;
    const a = (i / (points * 2)) * TAU - Math.PI / 2;
    const px = x + Math.cos(a) * r;
    const py = y + Math.sin(a) * r;
    if (i === 0) g.moveTo(px, py); else g.lineTo(px, py);
  }
  g.closePath();
  g.fillStyle = color;
  g.fill();
}

import {
  W, H, RIVER, POS, GATE, TREE_PALETTES, TAU,
  clamp, mulberry32, distanceToPath, insideClearing, inRiver, inReserved,
  PATH_SAMPLES
} from './config.js';
import { makeTreeSprite, makePalmSprite, makeBushSprite } from './scenery.js';
import { paintGround } from './terrain.js';

function buildRiverShape() {
  const left = [];
  const right = [];
  for (let y = -50; y <= H + 50; y += 28) {
    left.push([RIVER.x1 + Math.sin(y * 0.019 + 1.4) * 7 + Math.sin(y * 0.0061 + 0.4) * 5, y]);
    right.push([RIVER.x2 + Math.sin(y * 0.017 + 3.2) * 8 + Math.cos(y * 0.0053) * 4, y]);
  }
  const path = new Path2D();
  path.moveTo(left[0][0], left[0][1]);
  for (let i = 1; i < left.length; i += 1) path.lineTo(left[i][0], left[i][1]);
  for (let i = right.length - 1; i >= 0; i -= 1) path.lineTo(right[i][0], right[i][1]);
  path.closePath();
  return { left, right, path };
}

export function createWorld() {
  const rand = mulberry32(0x51EDBEEF);
  const world = {
    ground: null,
    sprites: {
      trees: [],
      palms: [],
      bushes: []
    },
    trees: [],
    bushes: [],
    props: [],
    obstacles: [],
    scenery: [],
    glints: [],
    fireflies: [],
    goldMotes: [],
    pathSamples: PATH_SAMPLES,
    river: buildRiverShape(),
    gate: { progress: 0 },
    canoe: { x: 1068, y: 900, side: 'west' },
    cave: { x: 250, y: 1580, rx: 315, ry: 330 },
    glyphs: { jaguar: { x: POS.shrine.x, y: POS.shrine.y }, serpent: { x: POS.caveStone.x, y: POS.caveStone.y }, sun: { x: POS.sunStone.x, y: POS.sunStone.y } }
  };

  for (let i = 0; i < 6; i += 1) world.sprites.trees.push(makeTreeSprite(TREE_PALETTES[i], mulberry32(1000 + i * 77)));
  for (let i = 0; i < 3; i += 1) world.sprites.palms.push(makePalmSprite(mulberry32(2000 + i * 31), i));
  for (let i = 0; i < 4; i += 1) world.sprites.bushes.push(makeBushSprite(mulberry32(3000 + i * 19), i));

  const treePoints = [];

  function canPlaceTree(x, y, radius) {
    if (x < 70 || x > W - 70 || y < 70 || y > H - 70) return false;
    if (inRiver(x, y, 46)) return false;
    if (insideClearing(x, y, 1.04)) return false;
    if (distanceToPath(x, y) < 72) return false;
    if (inReserved(x, y, 16)) return false;
    for (const p of treePoints) {
      if ((p[0] - x) ** 2 + (p[1] - y) ** 2 < (radius + p[2] + 32) ** 2) return false;
    }
    return true;
  }

  // Dense jungle canopy.
  for (let gy = 80; gy < H; gy += 122) {
    for (let gx = 80; gx < W; gx += 126) {
      if (rand() < 0.43) continue;
      const x = gx + (rand() - 0.5) * 86;
      const y = gy + (rand() - 0.5) * 80;
      const s = 0.78 + rand() * 0.52;
      const variant = Math.floor(rand() * 6);
      if (!canPlaceTree(x, y, 42 * s)) continue;
      treePoints.push([x, y, 40 * s]);
      world.trees.push({ kind: 'tree', x, y, s, variant, sprite: world.sprites.trees[variant], ax: 160, ay: 340, bw: 320, bh: 360, radius: 15 * s });
      world.obstacles.push({ type: 'circle', x, y: y - 4, r: 15 * s });
    }
  }

  // Palms leaning over the river.
  for (const side of [-1, 1]) {
    for (let i = 0; i < 20; i += 1) {
      const y = 90 + rand() * (H - 180);
      if (y > 790 && y < 1010) continue;
      const x = side < 0 ? RIVER.x1 - 28 - rand() * 66 : RIVER.x2 + 28 + rand() * 66;
      if (distanceToPath(x, y) < 46) continue;
      if (insideClearing(x, y, 0.98)) continue;
      const s = 0.8 + rand() * 0.4;
      const variant = Math.floor(rand() * 3);
      world.trees.push({ kind: 'palm', x, y, s, variant, sprite: world.sprites.palms[variant], ax: 130, ay: 348, bw: 260, bh: 370, radius: 10 * s });
      world.obstacles.push({ type: 'circle', x, y: y - 3, r: 11 * s });
    }
  }

  // Understory.
  for (let i = 0; i < 190; i += 1) {
    const x = 60 + rand() * (W - 120);
    const y = 60 + rand() * (H - 120);
    if (inRiver(x, y, 22)) continue;
    if (insideClearing(x, y, 0.93)) continue;
    if (distanceToPath(x, y) < 38) continue;
    if (inReserved(x, y, 8)) continue;
    const s = 0.65 + rand() * 0.55;
    world.bushes.push({ kind: 'bush', x, y, s, sprite: world.sprites.bushes[Math.floor(rand() * 4)], ax: 90, ay: 132, bw: 180, bh: 150 });
  }

  const props = [
    { kind: 'banner', x: POS.banner.x, y: POS.banner.y, s: 1 },
    { kind: 'tent', x: POS.tentA.x, y: POS.tentA.y + 24, s: 1.08 },
    { kind: 'tent', x: POS.tentB.x, y: POS.tentB.y + 26, s: 0.94, flip: true },
    { kind: 'crate', x: POS.crate.x, y: POS.crate.y + 12, s: 1 },
    { kind: 'campfire', x: POS.campfire.x, y: POS.campfire.y + 6, s: 1 },
    { kind: 'torch', x: POS.torch.x, y: POS.torch.y + 10, s: 1 },
    { kind: 'shrineArch', x: 650, y: 520, s: 1 },
    { kind: 'altar', variant: 'jaguar', x: POS.altarJaguar.x, y: POS.altarJaguar.y + 28, s: 1 },
    { kind: 'vines', x: POS.vines.x, y: POS.vines.y + 16, s: 1 },
    { kind: 'caveMouth', x: POS.caveMouth.x, y: POS.caveMouth.y + 18, s: 1 },
    { kind: 'pillar', x: 1535, y: 692, s: 1, broken: false },
    { kind: 'pillar', x: 1618, y: 1088, s: 0.9, broken: true },
    { kind: 'pillar', x: 2188, y: 628, s: 1.12, broken: false },
    { kind: 'pillar', x: 2518, y: 1052, s: 0.86, broken: true },
    { kind: 'pillar', x: 1832, y: 1048, s: 0.8, broken: true },
    { kind: 'giantHead', x: 1868, y: 1132, s: 1 },
    { kind: 'guardian', x: 2708, y: 748, s: 1, flip: false },
    { kind: 'guardian', x: 2708, y: 1052, s: 1, flip: true },
    { kind: 'gate', x: GATE.x, y: GATE.y, s: 1 },
    { kind: 'guardian', x: 3106, y: 1246, s: 1.05, flip: true, gold: true }
  ];

  world.props = props;
  world.scenery = [...world.trees, ...world.bushes, ...props];

  // Obstacles for solid props.
  const addCircle = (x, y, r) => world.obstacles.push({ type: 'circle', x, y, r });
  addCircle(POS.tentA.x, POS.tentA.y + 6, 46);
  addCircle(POS.tentB.x, POS.tentB.y + 6, 40);
  addCircle(POS.crate.x, POS.crate.y + 2, 17);
  addCircle(POS.campfire.x, POS.campfire.y + 2, 21);
  addCircle(POS.yara.x, POS.yara.y, 11);
  addCircle(580, 492, 16);
  addCircle(720, 492, 16);
  addCircle(POS.altarJaguar.x, POS.altarJaguar.y + 6, 34);
  addCircle(128, 1392, 56);
  addCircle(372, 1392, 56);
  for (const p of props) {
    if (p.kind === 'pillar') addCircle(p.x, p.y - 4, 21 * p.s);
    if (p.kind === 'guardian') addCircle(p.x, p.y - 4, 22 * p.s);
    if (p.kind === 'giantHead') addCircle(p.x, p.y - 8, 44 * p.s);
  }
  world.obstacles.push({ type: 'rect', x: 3018, y: 452, w: 512, h: 492 });
  world.obstacles.push({ type: 'rect', x: GATE.wallX1, y: 520, w: GATE.wallX2 - GATE.wallX1, h: GATE.gapTop - 520 });
  world.obstacles.push({ type: 'rect', x: GATE.wallX1, y: GATE.gapBottom, w: GATE.wallX2 - GATE.wallX1, h: 520 });

  // Animated river sparkles.
  for (let i = 0; i < 100; i += 1) {
    world.glints.push({
      x: RIVER.x1 + 16 + rand() * (RIVER.x2 - RIVER.x1 - 32),
      y: rand() * (H + 160) - 80,
      len: 3 + rand() * 14,
      speed: 10 + rand() * 26,
      alpha: 0.05 + rand() * 0.16,
      phase: rand() * TAU
    });
  }

  // Fireflies and gold motes.
  const fireflySpots = [
    [420, 980, 360, 300], [1180, 900, 340, 500], [2020, 900, 430, 340], [650, 380, 170, 170], [2835, 900, 200, 250]
  ];
  for (let i = 0; i < 78; i += 1) {
    const spot = fireflySpots[Math.floor(rand() * fireflySpots.length)];
    world.fireflies.push({
      x: spot[0] + (rand() - 0.5) * spot[2],
      y: spot[1] + (rand() - 0.5) * spot[3],
      phase: rand() * TAU,
      speed: 0.25 + rand() * 0.55,
      radius: 8 + rand() * 22,
      size: 1.2 + rand() * 1.7
    });
  }
  for (let i = 0; i < 46; i += 1) {
    world.goldMotes.push({
      x: 2920 + rand() * 600,
      y: 600 + rand() * 900,
      phase: rand() * TAU,
      speed: 0.2 + rand() * 0.5,
      radius: 10 + rand() * 26,
      size: 1 + rand() * 2.1
    });
  }

  world.ground = paintGround(world, mulberry32(0xC0FFEE));
  return world;
}

export function drawWater(g, world, time) {
  g.save();
  g.clip(world.river.path);

  const grad = g.createLinearGradient(RIVER.x1, 0, RIVER.x2, 0);
  grad.addColorStop(0, 'rgba(8, 43, 45, .35)');
  grad.addColorStop(0.22, 'rgba(20, 89, 88, .12)');
  grad.addColorStop(0.55, 'rgba(53, 151, 138, .08)');
  grad.addColorStop(1, 'rgba(8, 40, 43, .42)');
  g.fillStyle = grad;
  g.fillRect(RIVER.x1 - 30, 0, RIVER.x2 - RIVER.x1 + 60, H);

  // Soft moving bands.
  for (let i = 0; i < 9; i += 1) {
    const y = ((i * 233 + time * 14) % (H + 300)) - 150;
    g.globalAlpha = 0.035 + (i % 3) * 0.012;
    g.fillStyle = '#b7efe2';
    g.fillRect(RIVER.x1, y, RIVER.x2 - RIVER.x1, 44 + (i % 4) * 32);
  }

  // Sparkles.
  for (const s of world.glints) {
    const y = ((s.y + time * s.speed) % (H + 160)) - 80;
    const x = s.x + Math.sin(time * 0.8 + s.phase) * 5;
    const a = s.alpha * (0.55 + 0.45 * Math.sin(time * 1.7 + s.phase));
    g.globalAlpha = a;
    g.fillStyle = '#d9fff5';
    g.beginPath();
    g.ellipse(x, y, s.len * 0.5, 0.9, 0, 0, TAU);
    g.fill();
  }

  // Little ripples.
  g.globalAlpha = 1;
  for (let i = 0; i < 5; i += 1) {
    const y = 300 + i * 330 + Math.sin(time * 0.4 + i) * 26;
    g.strokeStyle = 'rgba(196, 245, 229, .13)';
    g.lineWidth = 1;
    g.beginPath();
    g.ellipse(RIVER.x1 + 34 + i * 24, y, 20 + (i % 3) * 9, 4, 0, 0, TAU);
    g.stroke();
  }
  g.restore();

  // Foam along the banks.
  g.save();
  g.lineCap = 'round';
  for (const side of [world.river.left, world.river.right]) {
    for (let i = 2; i < side.length - 2; i += 3) {
      const [x, y] = side[i];
      const shimmer = 0.5 + 0.5 * Math.sin(time * 1.3 + y * 0.05);
      g.globalAlpha = 0.08 + shimmer * 0.13;
      g.strokeStyle = '#d7f7e7';
      g.lineWidth = 1.2;
      g.beginPath();
      g.moveTo(x, y);
      g.lineTo(x + Math.sin(time + y) * 7, y + 1);
      g.stroke();
    }
  }
  g.restore();
}

import { TAU, blob, ellipse } from './config.js';

function canvasSprite(width, height, draw) {
  const c = document.createElement('canvas');
  const ss = 2;
  c.width = width * ss;
  c.height = height * ss;
  const g = c.getContext('2d');
  g.scale(ss, ss);
  draw(g);
  return c;
}

export function makeTreeSprite(pal, rand) {
  return canvasSprite(320, 360, g => {
    // Ground shadow.
    g.save();
    g.globalAlpha = 0.42;
    ellipse(g, 160, 338, 92, 23, '#041009');
    g.restore();

    // Roots.
    g.fillStyle = '#3a2a1b';
    g.beginPath();
    g.moveTo(134, 336);
    g.quadraticCurveTo(120, 330, 112, 342);
    g.quadraticCurveTo(136, 342, 144, 330);
    g.closePath();
    g.fill();
    g.beginPath();
    g.moveTo(176, 336);
    g.quadraticCurveTo(196, 326, 208, 342);
    g.quadraticCurveTo(184, 342, 172, 330);
    g.closePath();
    g.fill();

    // Trunk.
    const trunk = g.createLinearGradient(145, 0, 178, 0);
    trunk.addColorStop(0, '#5b4128');
    trunk.addColorStop(0.45, '#7a5a36');
    trunk.addColorStop(1, '#3a2919');
    g.fillStyle = trunk;
    g.beginPath();
    g.moveTo(150, 338);
    g.bezierCurveTo(146, 300, 148, 250, 154, 214);
    g.lineTo(170, 214);
    g.bezierCurveTo(174, 252, 176, 300, 170, 338);
    g.closePath();
    g.fill();
    g.strokeStyle = 'rgba(38, 25, 13, .55)';
    g.lineWidth = 1.2;
    for (let i = 0; i < 6; i += 1) {
      const y = 230 + i * 17;
      g.beginPath();
      g.moveTo(153 + i * 0.4, y);
      g.quadraticCurveTo(159, y + 4, 166, y - 1);
      g.stroke();
    }

    // Canopy: layered organic clusters.
    const clusters = [];
    for (let i = 0; i < 14; i += 1) {
      const a = rand() * TAU;
      const rr = 18 + rand() * 72;
      clusters.push({
        x: 160 + Math.cos(a) * rr * 1.4,
        y: 154 + Math.sin(a) * rr * 0.8,
        rx: 40 + rand() * 32,
        ry: 32 + rand() * 24,
        rot: rand() * TAU
      });
    }

    g.save();
    g.globalAlpha = 0.95;
    for (const c of clusters) {
      blob(g, c.x + 2, c.y + 15, c.rx, c.ry, 10, rand, c.rot);
      g.fillStyle = pal.dark;
      g.fill();
    }
    for (const c of clusters) {
      blob(g, c.x - 2, c.y - 2, c.rx * 0.92, c.ry * 0.9, 10, rand, c.rot + 0.2);
      g.fillStyle = pal.mid;
      g.fill();
    }
    for (const c of clusters) {
      blob(g, c.x - 8, c.y - 13, c.rx * 0.72, c.ry * 0.68, 9, rand, c.rot + 0.4);
      g.fillStyle = pal.light;
      g.fill();
    }
    for (const c of clusters) {
      blob(g, c.x - 14, c.y - 24, c.rx * 0.48, c.ry * 0.45, 8, rand, c.rot + 0.6);
      g.globalAlpha = 0.75;
      g.fillStyle = pal.hi;
      g.fill();
      g.globalAlpha = 0.95;
    }
    g.restore();

    // Sunlit rim on the upper-left.
    g.save();
    g.globalAlpha = 0.26;
    for (let i = 0; i < 18; i += 1) {
      const a = -2.7 + rand() * 1.6;
      const rr = 74 + rand() * 54;
      const x = 160 + Math.cos(a) * rr;
      const y = 150 + Math.sin(a) * rr * 0.8;
      ellipse(g, x, y, 7 + rand() * 12, 3 + rand() * 6, pal.rim);
    }
    g.restore();

    // Leaf speckles.
    for (let i = 0; i < 90; i += 1) {
      const a = rand() * TAU;
      const rr = rand() ** 0.6 * 108;
      const x = 160 + Math.cos(a) * rr * 1.2;
      const y = 152 + Math.sin(a) * rr * 0.72;
      g.globalAlpha = 0.25 + rand() * 0.35;
      g.fillStyle = rand() > 0.45 ? pal.hi : pal.dark;
      g.beginPath();
      g.ellipse(x, y, 1.1 + rand() * 2.2, 0.7 + rand() * 1.3, rand() * TAU, 0, TAU);
      g.fill();
    }
    g.globalAlpha = 1;

    // Hanging vines.
    for (let i = 0; i < 4; i += 1) {
      const x = 118 + rand() * 86;
      const len = 34 + rand() * 58;
      g.strokeStyle = i % 2 ? '#3d7b46' : '#2d5e37';
      g.lineWidth = 1.4;
      g.beginPath();
      g.moveTo(x, 220);
      g.bezierCurveTo(x - 7, 240, x + 8, 250, x - 3, 220 + len);
      g.stroke();
      for (let j = 0; j < 4; j += 1) {
        const yy = 232 + (len / 5) * j;
        g.fillStyle = '#4c9657';
        g.beginPath();
        g.ellipse(x + (j % 2 ? 3 : -3), yy, 3.2, 1.6, 0.6, 0, TAU);
        g.fill();
      }
    }

    // A few bright bromeliads.
    for (let i = 0; i < 3; i += 1) {
      const x = 120 + rand() * 80;
      const y = 178 + rand() * 56;
      g.fillStyle = '#b84f36';
      for (let j = 0; j < 5; j += 1) {
        const a = (j / 5) * TAU;
        g.beginPath();
        g.ellipse(x + Math.cos(a) * 3.5, y + Math.sin(a) * 3.5, 2.6, 1.2, a, 0, TAU);
        g.fill();
      }
      g.fillStyle = '#e7b856';
      g.beginPath();
      g.arc(x, y, 1.7, 0, TAU);
      g.fill();
    }
  });
}

export function makePalmSprite(rand, variant) {
  const greens = [
    ['#1a4a2d', '#2d6a3c', '#4b9254'],
    ['#174434', '#28634a', '#3f8c63'],
    ['#204c2a', '#336c39', '#58a04d']
  ][variant % 3];
  return canvasSprite(280, 380, g => {
    g.save();
    g.globalAlpha = 0.36;
    ellipse(g, 138, 354, 65, 18, '#03100a');
    g.restore();

    // Curved trunk.
    const trunk = g.createLinearGradient(118, 0, 166, 0);
    trunk.addColorStop(0, '#503a24');
    trunk.addColorStop(0.5, '#87653c');
    trunk.addColorStop(1, '#392817');
    g.fillStyle = trunk;
    g.beginPath();
    g.moveTo(132, 354);
    g.bezierCurveTo(128, 300, 142, 240, 160, 194);
    g.lineTo(171, 197);
    g.bezierCurveTo(158, 246, 152, 304, 146, 354);
    g.closePath();
    g.fill();
    g.strokeStyle = 'rgba(50, 34, 18, .45)';
    g.lineWidth = 1.1;
    for (let i = 0; i < 12; i += 1) {
      const t = i / 12;
      const y = 348 - t * 148;
      g.beginPath();
      g.moveTo(132 + t * 30, y);
      g.lineTo(145 + t * 26, y - 2);
      g.stroke();
    }

    const cx = 165;
    const cy = 191;

    // Fronds.
    for (let i = 0; i < 9; i += 1) {
      const a = -Math.PI * 0.97 + (i / 8) * Math.PI * 1.1 + rand() * 0.1;
      const len = 88 + rand() * 28;
      const tipX = cx + Math.cos(a) * len;
      const tipY = cy + Math.sin(a) * len * 0.82 + 4;
      const perpX = -Math.sin(a);
      const perpY = Math.cos(a);
      const w = 14 + rand() * 4;
      g.fillStyle = greens[i % 2 ? 1 : 0];
      g.beginPath();
      g.moveTo(cx, cy);
      g.quadraticCurveTo(
        cx + Math.cos(a) * len * 0.5 + perpX * w,
        cy + Math.sin(a) * len * 0.5 * 0.82 + perpY * w,
        tipX, tipY
      );
      g.quadraticCurveTo(
        cx + Math.cos(a) * len * 0.5 - perpX * w * 0.5,
        cy + Math.sin(a) * len * 0.5 * 0.82 - perpY * w * 0.5,
        cx, cy
      );
      g.closePath();
      g.fill();
      g.strokeStyle = greens[2];
      g.globalAlpha = 0.6;
      g.lineWidth = 1;
      g.beginPath();
      g.moveTo(cx, cy);
      g.quadraticCurveTo(cx + Math.cos(a) * len * 0.55, cy + Math.sin(a) * len * 0.5, tipX, tipY);
      g.stroke();
      // Leaflets.
      for (let j = 1; j < 8; j += 1) {
        const t = j / 8;
        const px = cx + Math.cos(a) * len * t;
        const py = cy + Math.sin(a) * len * t * 0.82;
        g.globalAlpha = 0.38;
        g.lineWidth = 1;
        g.beginPath();
        g.moveTo(px, py);
        g.lineTo(px + perpX * 7 + Math.cos(a) * 2, py + perpY * 7);
        g.moveTo(px, py);
        g.lineTo(px - perpX * 6 + Math.cos(a) * 2, py - perpY * 6);
        g.stroke();
      }
      g.globalAlpha = 1;
    }

    // Coconuts.
    for (let i = 0; i < 3; i += 1) {
      g.fillStyle = i === 1 ? '#5f4a26' : '#4a381c';
      g.beginPath();
      g.arc(cx - 10 + i * 9, cy + 10 + (i % 2) * 5, 5.4, 0, TAU);
      g.fill();
      g.fillStyle = 'rgba(180, 150, 80, .35)';
      g.beginPath();
      g.arc(cx - 11.5 + i * 9, cy + 8 + (i % 2) * 5, 1.8, 0, TAU);
      g.fill();
    }
  });
}

export function makeBushSprite(rand, variant) {
  const palettes = [
    ['#173f27', '#235832', '#327342', '#65a35c'],
    ['#1b4325', '#2a6130', '#3f7c3e', '#78b063'],
    ['#153d2c', '#20583b', '#2f7149', '#5b9c69'],
    ['#1e4522', '#2d5e2b', '#467b36', '#7ca552']
  ];
  const pal = palettes[variant % palettes.length];
  return canvasSprite(180, 150, g => {
    g.save();
    g.globalAlpha = 0.3;
    ellipse(g, 90, 134, 52, 13, '#03100a');
    g.restore();

    if (variant === 3) {
      // Broad-leaf plant.
      for (let i = 0; i < 7; i += 1) {
        const a = -Math.PI * 0.92 + (i / 6) * Math.PI * 0.95;
        const len = 54 + rand() * 30;
        const x2 = 90 + Math.cos(a) * len;
        const y2 = 126 + Math.sin(a) * len * 0.86;
        g.fillStyle = i % 2 ? pal[1] : pal[2];
        g.beginPath();
        g.moveTo(90, 126);
        g.quadraticCurveTo(90 + Math.cos(a) * len * 0.5 - Math.sin(a) * 16, 126 + Math.sin(a) * len * 0.5 + Math.cos(a) * 16, x2, y2);
        g.quadraticCurveTo(90 + Math.cos(a) * len * 0.4 + Math.sin(a) * 6, 126 + Math.sin(a) * len * 0.4 - Math.cos(a) * 6, 90, 126);
        g.closePath();
        g.fill();
        g.strokeStyle = pal[3];
        g.globalAlpha = 0.5;
        g.beginPath();
        g.moveTo(90, 126);
        g.lineTo(x2, y2);
        g.stroke();
        g.globalAlpha = 1;
      }
    } else {
      const blobs = [];
      for (let i = 0; i < 7; i += 1) {
        const a = rand() * TAU;
        const rr = rand() * 32;
        blobs.push({ x: 90 + Math.cos(a) * rr, y: 100 + Math.sin(a) * rr * 0.55, rx: 24 + rand() * 18, ry: 20 + rand() * 13 });
      }
      for (const b of blobs) {
        blob(g, b.x + 2, b.y + 7, b.rx, b.ry, 9, rand);
        g.fillStyle = pal[0];
        g.fill();
      }
      for (const b of blobs) {
        blob(g, b.x - 1, b.y - 2, b.rx * 0.92, b.ry * 0.9, 9, rand);
        g.fillStyle = pal[1];
        g.fill();
      }
      for (const b of blobs) {
        blob(g, b.x - 5, b.y - 9, b.rx * 0.62, b.ry * 0.6, 8, rand);
        g.fillStyle = pal[2];
        g.fill();
      }
    }

    // Flowers or fruit.
    const flowerColors = ['#f0d9a0', '#e9a7a0', '#f2c46b', '#d9e3b0'];
    g.fillStyle = flowerColors[variant % 4];
    for (let i = 0; i < 6; i += 1) {
      const x = 58 + rand() * 64;
      const y = 74 + rand() * 42;
      const r = 1.5 + rand() * 1.5;
      g.beginPath();
      g.arc(x, y, r, 0, TAU);
      g.fill();
    }
  });
}

