  g.fillStyle = stone[0];
  rrect(g, -62, -14, 124, 20, 4);
  g.fill();
  g.fillStyle = stone[1];
  rrect(g, -52, -30, 104, 22, 3);
  g.fill();
  g.fillStyle = stone[2];
  rrect(g, -42, -46, 84, 20, 3);
  g.fill();
  g.fillStyle = stone[1];
  rrect(g, -48, -54, 96, 12, 2);
  g.fill();
  g.strokeStyle = 'rgba(29, 37, 25, .5)';
