import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.on('pageerror', e => console.log('PAGEERROR', e.message))
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForFunction(() => document.fonts.status === 'loaded')
await page.evaluate(() => window.__eldorado.startGame())
await page.waitForTimeout(500)
const shots = [
  ['cave-mouth', 250, 1290, {}],
  ['cave-inside', 250, 1600, { torch: true }],
  ['shrine', 650, 430, { machete: true, talked: true }],
  ['dock', 984, 900, { talked: true, machete: true, torch: true, vinesCut: true, jaguar: true, serpent: true }],
  ['ruins', 2320, 830, { talked: true, machete: true, torch: true, vinesCut: true, jaguar: true, serpent: true }],
  ['gate', 2780, 900, { talked: true, machete: true, torch: true, vinesCut: true, jaguar: true, serpent: true, sun: true }],
  ['city', 3260, 1080, { talked: true, machete: true, torch: true, vinesCut: true, jaguar: true, serpent: true, sun: true, gateOpen: true }]
]
for (const [name, x, y, flags] of shots) {
  if (Object.keys(flags).length) await page.evaluate(f => window.__eldorado.setFlags(f), flags)
  await page.evaluate(([x, y]) => window.__eldorado.teleport(x, y), [x, y])
  await page.waitForTimeout(900)
  await page.screenshot({ path: `/tmp/opencode/shot-${name}.png` })
  console.log('shot', name)
}
await browser.close()

