    g.lineWidth = 0.8 + rand() * 0.8;
    for (let j = 0; j < n; j += 1) {
      g.beginPath();
      g.moveTo(x + j * 2 - 2, y);
      g.quadraticCurveTo(x + (rand() - 0.5) * 8, y - 5, x + (rand() - 0.5) * 10, y - 8 - rand() * 8);
      g.stroke();
