import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch(config.browser.launchOptions)
for (const url of ['data:text/html,<h1>blank</h1>', 'http://localhost:3002']) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
  await page.goto(url, { waitUntil: 'load' })
  if (url.startsWith('http')) await page.waitForFunction(() => document.fonts.status === 'loaded')
  const result = await page.evaluate(() => new Promise(resolve => {
    let frames = 0; const times = []; const t0 = performance.now(); let last = t0
    function tick(now) {
      frames++; times.push(+(now - last).toFixed(1)); last = now
      if (now - t0 > 3000) resolve({ frames, dt: times })
      else requestAnimationFrame(tick)
    }
    requestAnimationFrame(tick)
  }))
  console.log(url.slice(0, 40), 'frames', result.frames, 'first dts', result.dt.slice(0, 12))
  await page.close()
}
await browser.close()

