import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { startForCapture } from '/home/runner/work/_temp/omgithub-runtime/scripts/capture-start.mjs'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 390, height: 844 } })
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForFunction(() => document.fonts.status === 'loaded')
await startForCapture(page, { enabled: true, selector: '' })
await page.waitForTimeout(1500)
const info = await page.evaluate(() => {
  const box = id => { const el = document.getElementById(id); if (!el) return null; const r = el.getBoundingClientRect(); const s = getComputedStyle(el); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), display: s.display, opacity: s.opacity, visibility: s.visibility } }
  return {
    body: document.body.className,
    touch: window.matchMedia('(pointer: coarse)').matches,
    maxTouch: navigator.maxTouchPoints,
    joystick: box('joystick'),
    action: box('action-btn'),
    touchControls: box('touch-controls'),
    compass: box('compass-wrap'),
    glyphCount: document.getElementById('glyph-count')?.textContent,
    canvas: box('game'),
  }
})
console.log(JSON.stringify(info, null, 2))
await page.screenshot({ path: '/tmp/opencode/mobile-before.png' })
await browser.close()

